pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint64 warpTime, uint128 amount) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 amt = bound(uint256(amount), 1 ether, 100 ether);
        uint64 t = uint64(bound(uint256(warpTime), 1, type(uint64).max - 2));

        vm.warp(t);
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(t + 1);

        // funds must stay locked until unlockTime: Collect before t+1 must revert
        vm.prank(actor);
        try c.Collect(uint256(amt)) {
            assertTrue(false, "funds withdrawn before unlockTime");
        } catch {
            assertTrue(true);
        }
    }
}

