// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 t, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        t = bound(t, 0, type(uint64).max);
        amount = bound(amount, 1, type(uint128).max);

        vm.warp(1_000_000);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        // General rule: after any Put, the holder's unlockTime is at least the
        // block timestamp at which the Put executed (past t is clamped to now).
        assertTrue(c.Acc(actor).unlockTime >= 1_000_000);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint _amount, uint _unlockTime) public {
        require(address(this).balance >= _amount);
        require(c.MinSum() <= _amount);
        require(_unlockTime > block.timestamp);

        c.Put{value: _amount}(_unlockTime);

        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, _amount));
        require(ok);

        (uint _ut, uint _bal) = c.Acc(address(this));
        assert(_bal == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}

