contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt) public {
        require(amt >= 1 ether);
        require(address(this).balance >= amt);

        // Deposit funds (via public Put) so a later Collect can succeed.
        c.Put{value: amt}(0);

        // Attempt the withdrawal and measure the gas it consumes.
        uint g0 = gasleft();
        c.Collect(amt);
        uint used = g0 - gasleft();

        // On P, a successful Collect also executes LogFile.AddMessage
        // (SLOAD of the log, struct stores, array push), consuming far
        // more gas than a bare balance update plus ETH transfer, which
        // is all M does after its edit.
        assert(used > 21000);
    }

    receive() external payable {}
    fallback() external payable {}
}
